"""Render an AI usage scan as a self-contained relationship graph.

The HTML includes its CSS, JavaScript, and graph data without external requests.
Channels use distinct colors for CLI, direct API, and local-model access. The
browser computes summary counts from the embedded nodes and edges.
"""
from __future__ import annotations

import json

_TEMPLATE = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>CodeSextant · AI Usage Map</title>\n<!--\n  codesextant --action ai-usage  · dark HUD relationship graph\n  Design language inherited from panel.py (same family as the daemon panel): deep black background, hairline borders, cyan as the primary accent, no CDN.\n  3-role semantic palette: cyan = code structure / orange = AI provider identity (scarce warm accent) / red = governance violation.\n  Renders from a single window.GRAPH = { meta, nodes, edges }; stats are recomputed by the JS from that graph, so they can never disagree with it.\n-->\n<style>\n  :root{\n    /* base: one step darker than panel, pure HUD black (OKLCH L≈0.055 / H≈250 / C≈0.012) */\n    --bg:#07090d; --bg-2:#0a0d13;\n    --surface:#0f141b; --surface-2:#0c1017; --surface-hi:#141b24;\n    /* hairline scale: an opacity ladder, not gray hex values */\n    --hair:rgba(255,255,255,.07); --hair-2:rgba(255,255,255,.12); --hair-3:rgba(255,255,255,.20);\n    --fg:#e6edf3; --dim:#8b949e; --faint:#5b6573; --faintest:#3a424e;\n    /* 3-role accent */\n    --cyan:#2dd4bf; --cyan-soft:rgba(45,212,191,.16); --cyan-glow:rgba(45,212,191,.45);\n    --orange:#f2933f; --orange-soft:rgba(242,147,63,.16); --orange-glow:rgba(242,147,63,.42);\n    --red:#f85149; --red-soft:rgba(248,81,73,.15); --red-glow:rgba(248,81,73,.5);\n    --ok:#3fb950;\n    --mono:ui-monospace,"Cascadia Code","JetBrains Mono","Consolas","Sarasa Mono TC",monospace;\n    --sans:"Segoe UI Variable","Segoe UI","Microsoft JhengHei",system-ui,-apple-system,sans-serif;\n    --r:12px; --r-sm:8px;\n    --dur:.34s; --spring:linear(0,.18 8%,.62 22%,.92 36%,1.06 50%,1.02 66%,.998 82%,1);\n  }\n  @media (prefers-reduced-motion: reduce){ :root{ --dur:.001s; --spring:linear(0,1); } }\n  *{ box-sizing:border-box; }\n  html,body{ height:100%; }\n  body{\n    margin:0; color:var(--fg); font-family:var(--sans); font-size:15px; line-height:1.55;\n    -webkit-font-smoothing:antialiased; overflow:hidden;\n    background:\n      radial-gradient(1200px 700px at 78% -12%, rgba(242,147,63,.06), transparent 60%),\n      radial-gradient(1100px 620px at 8% 8%, rgba(45,212,191,.05), transparent 58%),\n      var(--bg);\n  }\n\n  /* ── top chrome: recessive, hairline, achromatic ── */\n  header{\n    position:fixed; inset:0 0 auto 0; z-index:40; height:60px;\n    display:flex; align-items:center; gap:14px; padding:0 22px;\n    background:linear-gradient(180deg, rgba(8,10,14,.86), rgba(8,10,14,.55) 70%, transparent);\n    -webkit-backdrop-filter:blur(8px); backdrop-filter:blur(8px);\n  }\n  .brand{ display:flex; align-items:center; gap:11px; }\n  .brand .mk{\n    width:30px; height:30px; border-radius:9px; flex:none; position:relative;\n    background:conic-gradient(from 210deg, var(--cyan), #1c8c7f 40%, var(--orange) 78%, var(--cyan));\n    display:grid; place-items:center; color:#04201c; font-weight:800; font-size:15px;\n    box-shadow:0 0 0 1px var(--hair-2), 0 4px 18px -6px var(--cyan-glow);\n  }\n  h1{ font-size:16.5px; margin:0; font-weight:640; letter-spacing:.2px; }\n  h1 span{ color:var(--faint); font-weight:400; }\n  .sub{ font-size:12.5px; color:var(--dim); margin-top:1px; }\n  .path{ font-family:var(--mono); font-size:12px; color:var(--faint); margin-left:2px;\n    background:var(--surface); border:1px solid var(--hair); border-radius:999px; padding:3px 11px; }\n  .legend{ margin-left:auto; display:flex; gap:16px; align-items:center; font-size:12px; color:var(--dim); }\n  .legend i{ width:22px; height:2px; border-radius:2px; display:inline-block; vertical-align:middle; margin-right:6px; }\n  .legend .cli i{ background:var(--cyan); box-shadow:0 0 7px var(--cyan-glow); }\n  .legend .dir i{ background:var(--red); box-shadow:0 0 7px var(--red-glow); }\n  .legend .loc i{ background:var(--faint); }\n\n  /* ── stage ── */\n  #scroll{ position:absolute; inset:60px 0 0 0; overflow:auto; }\n  #stage{\n    position:relative; min-width:1040px; min-height:100%;\n    background:\n      radial-gradient(circle at 1px 1px, rgba(255,255,255,.032) 1px, transparent 0) 0 0 / 27px 27px;\n  }\n  #wires{ position:absolute; inset:0; width:100%; height:100%; pointer-events:none; z-index:1; overflow:visible; }\n  #wires path{ fill:none; transition:opacity var(--dur) ease, stroke-width var(--dur) ease; }\n  #wires path.edge-glow{ opacity:.5; }\n  #wires path.edge{ stroke-linecap:round; }\n\n  .col-label{\n    position:absolute; z-index:2; font-size:11px; letter-spacing:.14em; text-transform:uppercase;\n    color:var(--faintest); font-weight:600; -webkit-user-select:none; user-select:none;\n  }\n\n  /* ── node cards ── */\n  .node{\n    position:absolute; z-index:3; cursor:pointer; -webkit-user-select:none; user-select:none;\n    background:linear-gradient(180deg, var(--surface-hi), var(--surface));\n    border:1px solid var(--hair); border-radius:var(--r); padding:12px 14px;\n    box-shadow:0 1px 0 rgba(255,255,255,.03) inset, 0 10px 30px -18px rgba(0,0,0,.9);\n    transition:transform var(--dur) var(--spring), border-color .2s ease,\n               box-shadow .25s ease, opacity var(--dur) ease;\n    will-change:transform;\n  }\n  .node:hover{ border-color:var(--hair-3); transform:translateY(-2px);\n    box-shadow:0 14px 40px -18px rgba(0,0,0,1), 0 0 0 1px var(--hair-2); }\n  .node .row1{ display:flex; align-items:center; gap:9px; }\n  .node .ttl{ font-size:15px; font-weight:620; letter-spacing:.1px; color:var(--fg);\n    white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }\n  .node .desc{ font-size:12.5px; color:var(--dim); margin-top:3px; line-height:1.4;\n    white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }\n\n  /* file node favicon (document glyph) */\n  .fav{ width:22px; height:22px; border-radius:6px; flex:none; display:grid; place-items:center;\n    background:var(--surface-2); border:1px solid var(--hair-2); color:var(--dim); }\n  .fav svg{ width:13px; height:13px; }\n\n  /* provider node favicon (warm identity square + initial). Orange is the scarce warm identity colour */\n  .pfav{ width:26px; height:26px; border-radius:7px; flex:none; display:grid; place-items:center;\n    font-family:var(--mono); font-weight:800; font-size:13px; color:#1a0f04;\n    background:linear-gradient(150deg, var(--orange), #b5641f);\n    box-shadow:0 0 0 1px rgba(242,147,63,.4), 0 4px 14px -5px var(--orange-glow); }\n\n  /* embedded provider chips inside file cards */\n  .chips{ display:flex; flex-wrap:wrap; gap:5px; margin-top:9px; }\n  .chip{ font-family:var(--mono); font-size:10.5px; padding:2px 8px 2px 6px; border-radius:6px;\n    display:inline-flex; align-items:center; gap:5px; letter-spacing:.2px; }\n  .chip::before{ content:""; width:5px; height:5px; border-radius:50%; }\n  .chip.cli{ color:#a7f0e6; background:var(--cyan-soft); border:1px solid rgba(45,212,191,.3); }\n  .chip.cli::before{ background:var(--cyan); box-shadow:0 0 6px var(--cyan-glow); }\n  .chip.dir{ color:#ffb3ad; background:var(--red-soft); border:1px solid rgba(248,81,73,.34); }\n  .chip.dir::before{ background:var(--red); box-shadow:0 0 6px var(--red-glow); }\n  .chip.loc{ color:#c3ccd6; background:rgba(91,101,115,.18); border:1px solid rgba(91,101,115,.34); }\n  .chip.loc::before{ background:var(--faint); }\n\n  /* violation state: red left bar + glow */\n  .node.bad{ border-color:rgba(248,81,73,.32); }\n  .node.bad::before{ content:""; position:absolute; left:0; top:12px; bottom:12px; width:3px;\n    border-radius:3px; background:var(--red); box-shadow:0 0 10px var(--red-glow); }\n  .node.bad{ box-shadow:0 10px 30px -18px rgba(0,0,0,.9), 0 0 34px -14px var(--red-glow); }\n\n  /* provider node compliance accents */\n  .node.prov{ padding-top:12px; }\n  .node.prov .meta{ font-size:11.5px; color:var(--faint); font-family:var(--mono); margin-top:3px; }\n  .node.prov.ok::after{ content:""; position:absolute; left:14px; right:14px; top:0; height:2px;\n    border-radius:2px; background:linear-gradient(90deg, transparent, var(--cyan), transparent); opacity:.7; }\n  .node.prov.bad::after{ content:""; position:absolute; left:14px; right:14px; top:0; height:2px;\n    border-radius:2px; background:linear-gradient(90deg, transparent, var(--red), transparent); opacity:.8; }\n  .node.prov.ch-local:not(.bad)::after{ content:""; position:absolute; left:14px; right:14px; top:0; height:2px;\n    border-radius:2px; background:linear-gradient(90deg, transparent, var(--faint), transparent); opacity:.7; }\n  .tagpill{ margin-left:auto; font-size:10px; font-family:var(--mono); padding:2px 7px; border-radius:999px;\n    letter-spacing:.05em; }\n  .tagpill.ok{ color:#a7f0e6; border:1px solid rgba(45,212,191,.32); background:var(--cyan-soft); }\n  .tagpill.bad{ color:#ffb3ad; border:1px solid rgba(248,81,73,.36); background:var(--red-soft); }\n  .tagpill.loc{ color:#c3ccd6; border:1px solid rgba(91,101,115,.34); background:rgba(91,101,115,.16); }\n\n  /* dim / highlight during hover-focus */\n  #stage.focusing .node:not(.hot){ opacity:.28; }\n  #stage.focusing #wires path.edge:not(.hot),\n  #stage.focusing #wires path.edge-glow:not(.hot){ opacity:.07; }\n  #wires path.edge.hot{ stroke-width:2.4; }\n  #wires path.edge-glow.hot{ opacity:.9; }\n  .node.pin{ border-color:var(--hair-3); box-shadow:0 0 0 1px var(--cyan-soft), 0 16px 44px -18px rgba(0,0,0,1); }\n\n  /* ── metrics card (bottom-right HUD, foglamp-style) ── */\n  #metrics{\n    position:fixed; right:20px; bottom:20px; z-index:30; width:236px;\n    background:linear-gradient(180deg, rgba(20,27,36,.92), rgba(12,16,23,.92));\n    border:1px solid var(--hair-2); border-radius:14px; padding:14px 16px 13px;\n    -webkit-backdrop-filter:blur(10px); backdrop-filter:blur(10px); box-shadow:0 20px 50px -22px rgba(0,0,0,1);\n  }\n  #metrics h3{ margin:0 0 11px; font-size:11px; letter-spacing:.14em; text-transform:uppercase;\n    color:var(--faint); font-weight:600; display:flex; align-items:center; gap:7px; }\n  #metrics h3::before{ content:""; width:6px; height:6px; border-radius:50%; background:var(--orange);\n    box-shadow:0 0 8px var(--orange-glow); }\n  .mrow{ display:flex; align-items:baseline; justify-content:space-between; padding:5px 0;\n    border-bottom:1px dashed var(--hair); }\n  .mrow:last-child{ border-bottom:none; }\n  .mrow .lab{ font-size:12.5px; color:var(--dim); }\n  .mrow .val{ font-family:var(--mono); font-size:20px; font-weight:700; letter-spacing:-.02em; }\n  .val.c{ color:var(--fg); } .val.o{ color:var(--orange); } .val.g{ color:var(--cyan); } .val.r{ color:var(--red); }\n  .mrow .val.zero{ color:var(--ok); }\n\n  /* ── detail drawer (click node) ── */\n  #drawer{\n    position:fixed; top:60px; right:0; bottom:0; z-index:50; width:380px; max-width:90vw;\n    background:linear-gradient(180deg, var(--bg-2), var(--bg)); border-left:1px solid var(--hair-2);\n    transform:translateX(100%); transition:transform var(--dur) var(--spring);\n    box-shadow:-30px 0 60px -30px rgba(0,0,0,1); display:flex; flex-direction:column;\n  }\n  #drawer.open{ transform:translateX(0); }\n  #drawer .dh{ padding:18px 20px 14px; border-bottom:1px solid var(--hair); }\n  #drawer .dh .dt{ display:flex; align-items:center; gap:10px; }\n  #drawer .dh h2{ margin:0; font-size:17px; font-weight:640; }\n  #drawer .dh .dp{ font-family:var(--mono); font-size:12px; color:var(--faint); margin-top:6px; word-break:break-all; }\n  #drawer .dclose{ margin-left:auto; background:var(--surface); border:1px solid var(--hair); color:var(--dim);\n    width:28px; height:28px; border-radius:8px; cursor:pointer; font-size:15px; line-height:1; }\n  #drawer .dclose:hover{ color:var(--fg); border-color:var(--hair-3); }\n  #drawer .db{ padding:14px 20px 24px; overflow:auto; }\n  .site{ background:var(--surface-2); border:1px solid var(--hair); border-radius:10px; padding:11px 13px; margin-bottom:9px; }\n  .site .sh{ display:flex; align-items:center; gap:8px; font-family:var(--mono); font-size:12.5px; }\n  .site .sh .ln{ color:var(--cyan); } .site.dir .sh .ln{ color:var(--red); }\n  .site .badge{ margin-left:auto; font-size:10px; font-family:var(--mono); padding:2px 8px; border-radius:999px; }\n  .site .badge.cli{ color:#a7f0e6; background:var(--cyan-soft); border:1px solid rgba(45,212,191,.3); }\n  .site .badge.dir{ color:#ffb3ad; background:var(--red-soft); border:1px solid rgba(248,81,73,.34); }\n  .site .badge.loc{ color:#c3ccd6; background:rgba(91,101,115,.18); border:1px solid rgba(91,101,115,.3); }\n  .site.loc .sh .ln{ color:var(--dim); }\n  .site .snip{ font-family:var(--mono); font-size:11.5px; color:var(--dim); margin-top:8px;\n    background:var(--bg); border:1px solid var(--hair); border-radius:7px; padding:8px 10px;\n    white-space:pre-wrap; word-break:break-all; line-height:1.5; }\n  .site.dir .snip{ border-color:rgba(248,81,73,.22); }\n  .dhint{ font-size:12px; color:var(--faint); margin-top:6px; line-height:1.6; }\n</style>\n</head>\n<body>\n\n<header>\n  <div class="brand">\n    <div class="mk">CS</div>\n    <div>\n      <h1>AI Usage Map <span>· codesextant --action ai-usage</span></h1>\n      <div class="sub">Which AI/LLM services this repo uses · CLI subprocess (compliant) vs direct API (violation)</div>\n    </div>\n  </div>\n  <span class="path" id="hpath">&mdash;</span>\n  <div class="legend">\n    <span class="cli"><i></i>CLI subprocess (compliant)</span>\n    <span class="dir"><i></i>direct API (violation)</span>\n    <span class="loc"><i></i>local (not metered)</span>\n  </div>\n</header>\n\n<div id="scroll">\n  <div id="stage">\n    <svg id="wires" xmlns="http://www.w3.org/2000/svg"></svg>\n    <div class="col-label" id="lblFiles">consumers · files</div>\n    <div class="col-label" id="lblProv">providers · AI services</div>\n    <!-- node cards injected here -->\n  </div>\n</div>\n\n<aside id="metrics">\n  <h3>SCAN METRICS</h3>\n  <div class="mrow"><span class="lab">AI Providers</span><span class="val o" id="mProv">0</span></div>\n  <div class="mrow"><span class="lab">Consumer files</span><span class="val c" id="mFiles">0</span></div>\n  <div class="mrow"><span class="lab">CLI-compliant</span><span class="val g" id="mCli">0</span></div>\n  <div class="mrow"><span class="lab">Direct-API violations</span><span class="val r" id="mDir">0</span></div>\n  <div class="mrow"><span class="lab">Local</span><span class="val" id="mLoc" style="color:var(--faint)">0</span></div>\n</aside>\n\n<aside id="drawer">\n  <div class="dh">\n    <div class="dt">\n      <h2 id="drTitle">&mdash;</h2>\n      <button type="button" class="dclose" onclick="closeDrawer()">✕</button>\n    </div>\n    <div class="dp" id="drPath"></div>\n    <div class="dhint" id="drHint"></div>\n  </div>\n  <div class="db" id="drBody"></div>\n</aside>\n\n<script>\n/* ══════════════════ data contract: window.GRAPH = { meta, nodes, edges } ══════════════════\n * node.file     : { id, type:"file",     label, path, desc, providers:[id], violation:bool, sites:[{line,channel,provider,snippet}] }\n * node.provider : { id, type:"provider", label, initial, channel:"cli"|"direct", files:int, violation:bool }\n * edge          : { from:<file id>, to:<provider id>, channel:"cli"|"direct" }\n * Stats are not part of the data. The JS recomputes them from nodes/edges (single source of truth, can never disagree).\n * ────────────────────────────────────────────────────────────────────────────── */\nwindow.GRAPH = %%GRAPH_JSON%%;\n\n/* ── consts / helpers ── */\nconst NS = "http://www.w3.org/2000/svg";\nconst FILE_W = 288, PROV_W = 214, VGAP = 18, TOP = 56, PAD_X = 52;\nconst esc = s => String(s==null?"":s).replace(/[&<>"\']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",\'"\':"&quot;","\'":"&#39;"}[c]));\nconst FILE_SVG = \'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 3v5h5"/><path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/></svg>\';\n\nconst G = window.GRAPH;\nconst byId = {}; G.nodes.forEach(n => byId[n.id] = n);\nconst files = G.nodes.filter(n => n.type === "file");\nconst provs = G.nodes.filter(n => n.type === "provider");\nconst stage = document.getElementById("stage");\nconst scrollEl = document.getElementById("scroll");\nconst svg = document.getElementById("wires");\n\n/* adjacency for barycenter ordering + hover highlight */\nconst nbr = {}; G.nodes.forEach(n => nbr[n.id] = []);\nG.edges.forEach(e => { nbr[e.from].push(e.to); nbr[e.to].push(e.from); });\n\n/* ── 1) build cards (measure heights via reflow) ── */\nfunction providerChip(pid, channel){\n  const p = byId[pid]; const cls = channel==="direct" ? "dir" : (channel==="local" ? "loc" : "cli");\n  return `<span class="chip ${cls}">${esc(p ? p.label.toLowerCase() : pid)}</span>`;\n}\nfunction buildCards(){\n  [...files, ...provs].forEach(n => {\n    const el = document.createElement("div");\n    el.className = "node " + n.type + (n.type==="provider"?(" prov ch-"+(n.channel||"cli")):"") + (n.violation?" bad":" ok");\n    el.dataset.id = n.id;\n    el.style.width = (n.type==="file"?FILE_W:PROV_W) + "px";\n    if(n.type === "file"){\n      const chips = n.providers.map(pid => {\n        const site = (n.sites||[]).find(s => s.provider===pid);\n        return providerChip(pid, site ? site.channel : "cli");\n      }).join("");\n      el.innerHTML =\n        `<div class="row1"><div class="fav">${FILE_SVG}</div><div class="ttl">${esc(n.label)}</div></div>\n         <div class="desc">${esc(n.desc)}</div>\n         <div class="chips">${chips}</div>`;\n    } else {\n      const tag = n.violation ? `<span class="tagpill bad">direct</span>` : (n.channel==="local" ? `<span class="tagpill loc">local</span>` : `<span class="tagpill ok">cli</span>`);\n      el.innerHTML =\n        `<div class="row1"><div class="pfav">${esc(n.initial||n.label[0])}</div><div class="ttl">${esc(n.label)}</div>${tag}</div>\n         <div class="meta">${n.files} file${n.files>1?"s":""} · ${n.channel==="direct"?"direct API":(n.channel==="local"?"local model":"CLI subprocess")}</div>`;\n    }\n    el.addEventListener("mouseenter", () => focusNode(n.id));\n    el.addEventListener("mouseleave", () => { if(!pinned) clearFocus(); });\n    el.addEventListener("click", () => openDrawer(n.id));\n    stage.appendChild(el);\n    n._el = el; n._w = el.offsetWidth; n._h = el.offsetHeight; // forces layout → real height\n  });\n}\n\n/* ── 2) barycenter ordering (reduce edge crossings) ── */\nfunction order(){\n  files.forEach((n,i)=>n._i=i); provs.forEach((n,i)=>n._i=i);\n  const mean = (ids)=> ids.length ? ids.reduce((s,id)=>s+byId[id]._i,0)/ids.length : 0;\n  for(let k=0;k<4;k++){\n    provs.sort((a,b)=> mean(nbr[a.id]) - mean(nbr[b.id]));\n    provs.forEach((n,i)=>n._i=i);\n    files.sort((a,b)=> mean(nbr[a.id]) - mean(nbr[b.id]));\n    files.forEach((n,i)=>n._i=i);\n  }\n}\n\n/* ── 3) place columns + draw wires ── */\nfunction place(){\n  // Anchor the natural design width to the stable viewport, not to the stage itself\n  // (otherwise the explicit width shrinks a little on every pass). Clamping to\n  // 1040-1560 gives a balanced horizontal spread; the fit scale below absorbs any\n  // vertical overflow.\n  const W = Math.min(Math.max(scrollEl.clientWidth, 1040), 1560);\n  const leftX = PAD_X;\n  const rightX = W - PROV_W - PAD_X;\n  const stack = (list, x) => {\n    let cur = TOP;\n    list.forEach(n => { n._x = x; n._y = cur; cur += n._h + VGAP; });\n    return cur - VGAP - TOP; // column content height\n  };\n  const hF = stack(files, leftX);\n  const hP = stack(provs, rightX);\n  const maxH = Math.max(hF, hP);\n  // center the shorter column vertically\n  const shift = (list, colH) => { const off=(maxH-colH)/2; list.forEach(n=>n._y+=off); };\n  shift(files, hF); shift(provs, hP);\n  [...files,...provs].forEach(n => { n._el.style.left=n._x+"px"; n._el.style.top=n._y+"px"; });\n\n  const contentW = rightX + PROV_W + PAD_X;\n  const totalH = TOP + maxH + TOP;\n  stage.style.width = contentW + "px";\n  stage.style.height = totalH + "px";\n  svg.setAttribute("viewBox", `0 0 ${contentW} ${totalH}`);\n  svg.setAttribute("width", contentW); svg.setAttribute("height", totalH);\n\n  // fit-to-viewport: scale the whole graph into the visible area and centre it, so\n  // the entire map is visible at once. A useful side effect is that the fixed\n  // metrics HUD ends up over genuinely empty space in the bottom-right instead of\n  // covering provider nodes. Fall back to scrolling only when the content is so\n  // large that fitting it would cost readability (scale < 0.62).\n  const M = 26, vw = scrollEl.clientWidth, vh = scrollEl.clientHeight;\n  let s = Math.min(1, (vw - M*2)/contentW, (vh - M*2)/totalH);\n  if(s < 0.62){                       // too large: fall back to scrolling rather than shrinking the text\n    scrollEl.style.overflow = "auto"; stage.style.transform = "none";\n  } else {\n    scrollEl.style.overflow = "hidden";\n    const tx = Math.max(M, (vw - contentW*s)/2), ty = Math.max(M, (vh - totalH*s)/2);\n    stage.style.transformOrigin = "top left";\n    stage.style.transform = `translate(${tx}px,${ty}px) scale(${s})`;\n  }\n\n  // column labels\n  const lf=document.getElementById("lblFiles"), lp=document.getElementById("lblProv");\n  lf.style.left=leftX+"px"; lf.style.top=(TOP-26)+"px";\n  lp.style.left=rightX+"px"; lp.style.top=(TOP-26)+"px";\n\n  drawWires();\n}\n\nfunction drawWires(){\n  svg.innerHTML = "";\n  G.edges.forEach((e,idx) => {\n    const f = byId[e.from], p = byId[e.to];\n    const x1 = f._x + f._w, y1 = f._y + f._h/2;\n    const x2 = p._x,        y2 = p._y + p._h/2;\n    const c  = Math.max(56, (x2-x1)*0.42);\n    const d  = `M ${x1} ${y1} C ${x1+c} ${y1}, ${x2-c} ${y2}, ${x2} ${y2}`;\n    const col = e.channel==="direct" ? "var(--red)" : (e.channel==="local" ? "var(--faint)" : "var(--cyan)");\n    // wide soft underlay (glow) + crisp line\n    const glow = document.createElementNS(NS,"path");\n    glow.setAttribute("d",d); glow.setAttribute("class","edge-glow");\n    glow.setAttribute("stroke",col); glow.setAttribute("stroke-width","6");\n    glow.style.filter = "blur(3px)";\n    glow.dataset.f=e.from; glow.dataset.p=e.to;\n    const line = document.createElementNS(NS,"path");\n    line.setAttribute("d",d); line.setAttribute("class","edge");\n    line.setAttribute("stroke",col); line.setAttribute("stroke-width","1.6");\n    line.setAttribute("opacity", e.channel==="direct"?"0.85":"0.6");\n    line.dataset.f=e.from; line.dataset.p=e.to;\n    if(e.channel==="direct") line.setAttribute("stroke-dasharray","1 0"); // solid; kept for clarity\n    svg.appendChild(glow); svg.appendChild(line);\n  });\n}\n\n/* ── 4) hover focus / highlight ── */\nlet pinned = null;\nfunction focusNode(id){\n  const keep = new Set([id, ...nbr[id]]);\n  stage.classList.add("focusing");\n  document.querySelectorAll(".node").forEach(el => el.classList.toggle("hot", keep.has(el.dataset.id)));\n  svg.querySelectorAll("path").forEach(pt => {\n    const on = pt.dataset.f===id || pt.dataset.p===id;\n    pt.classList.toggle("hot", on);\n  });\n}\nfunction clearFocus(){\n  stage.classList.remove("focusing");\n  document.querySelectorAll(".node.hot").forEach(el=>el.classList.remove("hot"));\n  svg.querySelectorAll("path.hot").forEach(pt=>pt.classList.remove("hot"));\n}\n\n/* ── 5) detail drawer (click → expand call sites) ── */\nconst drawer=document.getElementById("drawer");\nfunction openDrawer(id){\n  const n = byId[id];\n  pinned = id; focusNode(id);\n  document.querySelectorAll(".node.pin").forEach(el=>el.classList.remove("pin"));\n  n._el.classList.add("pin");\n  document.getElementById("drTitle").textContent = n.label;\n  document.getElementById("drPath").textContent = n.type==="file" ? n.path : (n.files+" consumer file(s)");\n  const body = document.getElementById("drBody");\n  const hint = document.getElementById("drHint");\n  if(n.type === "file"){\n    hint.textContent = n.violation ? "Contains direct-API calls. Route these through the claude CLI subprocess instead." : "No direct-API violations (CLI channel / local model).";\n    body.innerHTML = (n.sites||[]).map(s => `\n      <div class="site ${s.channel}">\n        <div class="sh"><span class="ln">${esc(byId[s.provider]?byId[s.provider].label:s.provider)}:${s.line}</span>\n          <span class="badge ${s.channel}">${s.channel==="direct"?"direct API":(s.channel==="local"?"local":"CLI")}</span></div>\n        <div class="snip">${esc(s.snippet)}</div>\n      </div>`).join("") || `<div class="dhint">No call sites recorded for this file.</div>`;\n  } else {\n    const users = files.filter(f => f.providers.includes(id));\n    hint.textContent = n.violation ? "Accessed through the direct API in at least one place, which violates dispatch_cli_only." : "Every consumer goes through the CLI subprocess · compliant.";\n    body.innerHTML = users.map(f => {\n      const s = (f.sites||[]).find(x=>x.provider===id) || {};\n      return `<div class="site ${s.channel||\'cli\'}">\n        <div class="sh"><span class="ln">${esc(f.label)}:${s.line||"?"}</span>\n          <span class="badge ${s.channel||\'cli\'}">${s.channel==="direct"?"direct API":(s.channel==="local"?"local":"CLI")}</span></div>\n        <div class="snip">${esc(s.snippet||f.path)}</div></div>`;\n    }).join("");\n  }\n  drawer.classList.add("open");\n}\nfunction closeDrawer(){\n  drawer.classList.remove("open");\n  pinned=null; clearFocus();\n  document.querySelectorAll(".node.pin").forEach(el=>el.classList.remove("pin"));\n}\nstage.addEventListener("click", e => { if(e.target===stage || e.target===svg) closeDrawer(); });\n\n/* ── 6) metrics (computed from graph = SSOT) ── */\nfunction metrics(){\n  const cli = G.edges.filter(e=>e.channel==="cli").length;\n  const dir = G.edges.filter(e=>e.channel==="direct").length;\n  const loc = G.edges.filter(e=>e.channel==="local").length;\n  document.getElementById("mProv").textContent  = provs.length;\n  document.getElementById("mFiles").textContent = files.length;\n  document.getElementById("mCli").textContent   = cli;\n  const ml = document.getElementById("mLoc"); if(ml) ml.textContent = loc;\n  const md = document.getElementById("mDir");\n  md.textContent = dir; if(dir===0) md.classList.add("zero");\n  document.getElementById("hpath").textContent = G.meta.project + "  ·  " + G.meta.files_total + " files scanned";\n}\n\n/* ── boot ── */\nfunction render(){ stage.querySelectorAll(".node").forEach(el=>el.remove());\n  buildCards(); order(); place(); metrics(); }\nrender();\nlet rt; window.addEventListener("resize", ()=>{ clearTimeout(rt); rt=setTimeout(()=>{ place(); }, 120); });\n</script>\n</body>\n</html>\n'


def render_ai_usage(result: dict) -> str:
    """Render ``meta``, ``nodes``, and ``edges`` as self-contained HTML.

    Snippets and paths are escaped on display by the template. The embedded JSON
    also escapes script-closing and line-separator sequences before insertion.
    """
    graph = {
        "meta": result.get("meta", {}),
        "nodes": result.get("nodes", []),
        "edges": result.get("edges", []),
    }
    payload = (
        json.dumps(graph, ensure_ascii=False)
        .replace("</", "<\\/")            # stop </script> from closing the tag early (real XSS surface)
        .replace("<!--", "<\\!--")        # stop HTML comment sequences from interfering
        .replace(" ", "\\u2028")     # a line terminator in JS, cuts the statement short
        .replace(" ", "\\u2029")
    )
    return _TEMPLATE.replace("%%GRAPH_JSON%%", payload)
